"""Exact arithmetic and unit conversions — never generated by a model.

``evaluate`` parses the expression with ``ast`` and walks a whitelist of nodes (no
``eval``), after normalising spoken French ("17 fois 23", "racine carrée de 2",
"3,5 au carré", "20 % de 150"). ``convert`` handles lengths, masses, temperatures,
volumes, speeds, data sizes, durations and energies (French names and symbols).
"""
from __future__ import annotations

import ast
import math
import operator
import re
import unicodedata

from pydantic import AliasChoices, Field, model_validator

from .base import Params, Source, ToolError, ToolResult, fr_num, fr_sig, now_iso, tool

MAX_EXPR_CHARS = 300
MAX_NODES = 200
MAX_EXPONENT = 10_000
MAX_RESULT_DIGITS = 1000
MAX_FACTORIAL = 500


# --------------------------------------------------------------------------- French normalisation

def _strip_accents(text: str) -> str:
    return ''.join(c for c in unicodedata.normalize('NFD', text) if unicodedata.category(c) != 'Mn')


_SYMBOLS = {
    '×': '*', '✕': '*', '✖': '*', '∙': '*', '·': '*', '⋅': '*', '÷': '/', '∶': '/', '−': '-', '–': '-',
    '—': '-', '²': '**2', '³': '**3', '√': 'sqrt', 'π': 'pi', '^': '**', ' ': ' ', ' ': ' ',
    '[': '(', ']': ')', '{': '(', '}': ')', ';': ',',
}
_FILLER = re.compile(
    r"\b(combien|font|fait|faut|vaut|valent|calcule[rz]?|calcul|quel(?:le)?|est|le|la|les|resultat|que|qu|ca|"
    r"egal(?:e|ent)?|c|a|svp|stp|merci|donne|moi|dis|peux|tu|aurora|astra|s il te plait|s il vous plait)\b")


def normalize_expression(text: str) -> str:
    """French spoken/written arithmetic -> Python expression syntax (not yet validated)."""
    s = (text or '').strip()
    for k, v in _SYMBOLS.items():
        s = s.replace(k, v)
    s = _strip_accents(s.lower()).replace("'", ' ').replace('’', ' ')
    s = re.sub(r'(?<=\d) (?=\d{3}\b)', '', s)               # 1 000 000 -> 1000000
    s = re.sub(r'(?<=\d),(?=\d)', '.', s)                    # decimal comma
    num = r'(\d+(?:\.\d+)?|\([^()]*\)|pi|e)'
    s = re.sub(r'racine\s+cubique\s+(?:de\s+|d\s+)?' + num, r'cbrt(\1)', s)
    s = re.sub(r'racine(?:\s+carree)?\s+(?:de\s+|d\s+)?' + num, r'sqrt(\1)', s)
    s = re.sub(r'\bau\s+carre\b', '**2', s)
    s = re.sub(r'\bau\s+cube\b', '**3', s)
    s = re.sub(r'(\d+(?:\.\d+)?)\s*(?:%|pour\s*cents?|pourcents?)\s+(?:de|des|du|d)\s+', r'(\1/100)*', s)
    s = re.sub(r'\b(?:a\s+la\s+)?puissance\b', '**', s)
    s = re.sub(r'\bexposant\b', '**', s)
    s = re.sub(r'\bmultiplie(?:e|s)?\s+par\b|\bfois\b', '*', s)
    s = re.sub(r'\bdivise(?:e|s)?\s+par\b|\bsur\b', '/', s)
    s = re.sub(r'\bplus\b', '+', s)
    s = re.sub(r'\bmoins\b', '-', s)
    s = re.sub(r'\bmodulo\b|\bmod\b', '%', s)
    s = re.sub(r'(?<=[\d)])\s*x\s*(?=[\d(])', '*', s)       # 3 x 4
    s = re.sub(r'(\d+(?:\.\d+)?)\s*%(?!\s*[\d(a-z])', r'(\1/100)', s)  # "50 %" alone = 0.5
    s = re.sub(r'\bde\b|\bdu\b|\bd\b', ' ', s)
    s = _FILLER.sub(' ', s)
    s = s.replace('?', ' ').replace('!', ' ')
    s = re.sub(r'=\s*$', '', s.strip())
    s = re.sub(r'(?<=\d)\s*(?=\()', '*', s)                 # 2(3+4)
    s = re.sub(r'(?<=\))\s*(?=[\d(])', '*', s)              # (1+2)(3+4)
    s = re.sub(r'(?<=\d)\s*(?=(?!e[+-]?\d)[a-z])', '*', s)  # 2pi, 3sqrt(2) (keeps 1e5)
    return re.sub(r'\s+', ' ', s).strip()


def pretty(expr: str) -> str:
    out = re.sub(r'\s*\*\*\s*', '^', expr).replace('*', ' × ').replace('/', ' ÷ ')
    out = re.sub(r'\s*([+\-])\s*', r' \1 ', out)
    out = re.sub(r'\(\s*-\s*', '(-', out)
    out = re.sub(r'^\s*-\s*', '-', out)
    out = re.sub(r'\s+', ' ', out).strip()
    # « 2 500 × 3 » was shown « 2500 × 3 = 7 500 » (B7, rapport §4.6): integers grouped like the result (fr_num);
    # a decimal part is never grouped.
    out = re.sub(r'(?<![\d.])\d{4,}', lambda m: fr_num(int(m.group()), 0), out)
    return out.replace('.', ',')


# --------------------------------------------------------------------------- AST evaluator

def _check_number(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ToolError('Seuls les nombres réels sont pris en charge.')
    if isinstance(value, float) and not math.isfinite(value):
        raise ToolError('Résultat non défini ou infini.')
    if isinstance(value, int) and value.bit_length() > MAX_RESULT_DIGITS * 3.33:
        raise ToolError(f'Nombre trop grand (plus de {MAX_RESULT_DIGITS} chiffres).')
    return value


def _pow(a, b):
    if abs(b) > MAX_EXPONENT:
        raise ToolError(f'Exposant trop grand (limite : {MAX_EXPONENT}).')
    if abs(a) > 1 and b > 0 and b * math.log10(abs(a)) > MAX_RESULT_DIGITS:
        raise ToolError(f'Résultat trop grand (plus de {MAX_RESULT_DIGITS} chiffres).')
    if a < 0 and isinstance(b, float) and not b.is_integer():
        raise ToolError("Puissance non réelle (base négative et exposant non entier).")
    if a == 0 and b < 0:
        raise ToolError('Division par zéro.')
    try:
        return a ** b
    except OverflowError:
        raise ToolError('Résultat trop grand.') from None


def _sqrt(x):
    if x < 0:
        raise ToolError("Racine carrée d'un nombre négatif : pas de résultat réel.")
    return math.sqrt(x)


def _log(x, base=None):
    if x <= 0 or (base is not None and (base <= 0 or base == 1)):
        raise ToolError('Logarithme hors domaine (argument strictement positif requis).')
    return math.log(x) if base is None else math.log(x, base)


def _factorial(n):
    if isinstance(n, float):
        if not n.is_integer():
            raise ToolError('La factorielle demande un entier positif.')
        n = int(n)
    if n < 0 or n > MAX_FACTORIAL:
        raise ToolError(f'Factorielle limitée aux entiers de 0 à {MAX_FACTORIAL}.')
    return math.factorial(n)


def _round(x, n=0):
    if not float(n).is_integer() or abs(n) > 15:
        raise ToolError("round : nombre de décimales entier entre -15 et 15.")
    return round(x, int(n)) if n else round(x)


def _gcd(a, b):
    if not (float(a).is_integer() and float(b).is_integer()):
        raise ToolError('pgcd : entiers requis.')
    return math.gcd(int(a), int(b))


def _lcm(a, b):
    if not (float(a).is_integer() and float(b).is_integer()):
        raise ToolError('ppcm : entiers requis.')
    return math.lcm(int(a), int(b))


FUNCTIONS = {
    'sqrt': _sqrt, 'racine': _sqrt, 'rac': _sqrt,
    'cbrt': lambda x: math.copysign(abs(x) ** (1 / 3), x),
    'abs': abs, 'round': _round, 'arrondi': _round, 'floor': math.floor, 'ceil': math.ceil,
    'exp': math.exp, 'ln': _log, 'log': _log, 'log10': math.log10, 'log2': math.log2,
    'sin': math.sin, 'cos': math.cos, 'tan': math.tan,
    'asin': math.asin, 'acos': math.acos, 'atan': math.atan, 'atan2': math.atan2,
    'arcsin': math.asin, 'arccos': math.acos, 'arctan': math.atan,
    'sinh': math.sinh, 'cosh': math.cosh, 'tanh': math.tanh,
    'degrees': math.degrees, 'radians': math.radians, 'deg': math.degrees, 'rad': math.radians,
    'factorial': _factorial, 'fact': _factorial, 'factorielle': _factorial,
    'min': min, 'max': max, 'hypot': math.hypot, 'gcd': _gcd, 'pgcd': _gcd, 'lcm': _lcm, 'ppcm': _lcm,
}
CONSTANTS = {'pi': math.pi, 'e': math.e, 'tau': math.tau, 'phi': (1 + math.sqrt(5)) / 2}

_BINOPS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv,
           ast.FloorDiv: operator.floordiv, ast.Mod: operator.mod, ast.Pow: _pow}
_UNOPS = {ast.UAdd: operator.pos, ast.USub: operator.neg}


class _Evaluator:
    def __init__(self) -> None:
        self.nodes = 0

    def visit(self, node):
        self.nodes += 1
        if self.nodes > MAX_NODES:
            raise ToolError('Expression trop complexe.')
        if isinstance(node, ast.Expression):
            return self.visit(node.body)
        if isinstance(node, ast.Constant):
            return _check_number(node.value)
        if isinstance(node, ast.Name):
            if node.id in CONSTANTS:
                return CONSTANTS[node.id]
            raise ToolError(f'Nom inconnu dans l\'expression : « {node.id} ».')
        if isinstance(node, ast.UnaryOp) and type(node.op) in _UNOPS:
            return _check_number(_UNOPS[type(node.op)](self.visit(node.operand)))
        if isinstance(node, ast.BinOp) and type(node.op) in _BINOPS:
            left, right = self.visit(node.left), self.visit(node.right)
            if isinstance(node.op, ast.Mult) and isinstance(left, int) and isinstance(right, int):
                if left.bit_length() + right.bit_length() > MAX_RESULT_DIGITS * 3.33:
                    raise ToolError('Résultat trop grand.')
            try:
                return _check_number(_BINOPS[type(node.op)](left, right))
            except ZeroDivisionError:
                raise ToolError('Division par zéro.') from None
            except OverflowError:
                raise ToolError('Résultat trop grand.') from None
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and not node.keywords:
            func = FUNCTIONS.get(node.func.id)
            if func is None:
                raise ToolError(f'Fonction non autorisée : « {node.func.id} ».')
            args = [self.visit(a) for a in node.args]
            try:
                return _check_number(func(*args))
            except ToolError:
                raise
            except TypeError:
                raise ToolError(f'Nombre d\'arguments incorrect pour {node.func.id}.') from None
            except (ValueError, OverflowError):
                raise ToolError(f'Valeur hors du domaine de la fonction {node.func.id}.') from None
        raise ToolError('Expression non autorisée : seuls les nombres, opérateurs et fonctions mathématiques sont acceptés.')


def evaluate_expression(expression: str) -> dict:
    raw = (expression or '').strip()
    if not raw:
        raise ToolError('Expression vide.')
    if len(raw) > MAX_EXPR_CHARS:
        raise ToolError(f'Expression trop longue (limite : {MAX_EXPR_CHARS} caractères).')
    normalized = normalize_expression(raw)
    if not normalized:
        raise ToolError('Aucune expression mathématique reconnue.')
    try:
        tree = ast.parse(normalized, mode='eval')
    except SyntaxError:
        raise ToolError(f'Expression mal formée : « {raw} ».') from None
    value = _Evaluator().visit(tree)
    if isinstance(value, float) and value.is_integer() and abs(value) < 1e15:
        value_out: int | float = int(value)
    else:
        value_out = value
    if isinstance(value_out, int) and abs(value_out) > 2 ** 53:
        text = fr_num(value_out, 0)
        json_value: float | int | None = float(value_out) if value_out.bit_length() < 1000 else None
    else:
        text = format_number(value_out)
        json_value = value_out if not isinstance(value_out, float) else float(repr(value_out))
    return {'expression': raw, 'normalized': normalized, 'pretty': pretty(normalized),
            'result': json_value, 'result_text': text, 'exact_integer': isinstance(value_out, int)}


def format_number(value) -> str:
    if isinstance(value, int):
        return fr_sig(value)
    if value != 0 and (abs(value) >= 1e15 or abs(value) < 1e-6):
        return fr_sig(value, 10)
    text = f'{value:.10g}'
    if 'e' in text:
        return fr_sig(value, 10)
    return fr_sig(float(text), 15)


