_UNITS: dict[str, list[tuple[str, float, str]]] = {}      # key (lower, no accents) -> [(dim, factor, symbol)]
_CASED: dict[str, tuple[str, float, str]] = {}            # exact-case symbols (MB vs Mb)


def _add(dim: str, factor: float, symbol: str, *aliases: str, cased: tuple[str, ...] = ()) -> None:
    for alias in (symbol, *aliases):
        key = _unit_key(alias)
        entries = _UNITS.setdefault(key, [])
        if not any(e[0] == dim for e in entries):
            entries.append((dim, factor, symbol))
    for c in cased:
        _CASED[c] = (dim, factor, symbol)


def _unit_key(text: str) -> str:
    k = (text or '').strip().lower().replace('å', 'angstrom')
    k = _strip_accents(k)
    k = k.replace('²', '2').replace('³', '3').replace('°', '').replace('œ', 'oe')
    k = re.sub(r'\s*/\s*', '/', k)
    k = re.sub(r'[\s\-_]+', ' ', k).strip().rstrip('.')
    k = re.sub(r'^(?:en|des|de|du|d) ', '', k)
    return k


