def _lookup(raw: str) -> list[tuple[str, float, str]]:
    text = (raw or '').strip().rstrip('.')
    if text in _CASED:
        return [_CASED[text]]
    key = _unit_key(text)
    if key in _UNITS:
        return _UNITS[key]
    singular = ' '.join(w[:-1] if len(w) > 3 and w.endswith(('s', 'x')) else w for w in key.split(' '))
    singular = singular.replace(' par ', ' par ')
    if singular in _UNITS:
        return _UNITS[singular]
    if key.endswith('s') and key[:-1] in _UNITS:
        return _UNITS[key[:-1]]
    return []


def _to_kelvin(value: float, symbol: str) -> float:
    if symbol == '°C':
        return value + 273.15
    if symbol == '°F':
        return (value - 32) * 5 / 9 + 273.15
    return value


def _from_kelvin(value: float, symbol: str) -> float:
    if symbol == '°C':
        return value - 273.15
    if symbol == '°F':
        return (value - 273.15) * 9 / 5 + 32
    return value


def convert_units(value: float, from_unit: str, to_unit: str) -> dict:
    if not math.isfinite(value):
        raise ToolError('Valeur numérique invalide.')
    for unit in (from_unit, to_unit):
        key = _unit_key(unit)
        if key in CURRENCIES or key.rstrip('s') in CURRENCIES or unit.strip().upper() in {'EUR', 'USD', 'GBP', 'CHF', 'JPY', 'CAD', 'DZD'}:
            raise ToolError('Conversion de devises non disponible : elle exige un taux de change du jour, '
                            'qu\'AURORA ne peut pas inventer.')
    src, dst = _lookup(from_unit), _lookup(to_unit)
    if not src:
        raise ToolError(f'Unité inconnue : « {from_unit} ».')
    if not dst:
        raise ToolError(f'Unité inconnue : « {to_unit} ».')
    pairs = [(a, b) for a in src for b in dst if a[0] == b[0]]
    if not pairs:
        a, b = src[0][0], dst[0][0]
        raise ToolError(f'Conversion impossible : « {from_unit} » est une unité de {DIMENSION_LABELS[a]}, '
                        f'« {to_unit} » une unité de {DIMENSION_LABELS[b]}.')
    (dim, f_from, s_from), (_, f_to, s_to) = pairs[0]
    if dim == 'temperature':
        kelvin = _to_kelvin(value, s_from)
        if kelvin < -1e-9:
            raise ToolError('Température inférieure au zéro absolu : impossible.')
        result = _from_kelvin(kelvin, s_to)
        formula = {'°C>K': 'K = °C + 273,15', 'K>°C': '°C = K − 273,15', '°C>°F': '°F = °C × 9/5 + 32',
                   '°F>°C': '°C = (°F − 32) × 5/9', '°F>K': 'K = (°F − 32) × 5/9 + 273,15',
                   'K>°F': '°F = (K − 273,15) × 9/5 + 32'}.get(f'{s_from}>{s_to}', 'identité')
        factor = None
    else:
        factor = f_from / f_to
        result = value * factor
        formula = f'1 {s_from} = {fr_sig(factor, 10)} {s_to}'
    if abs(result) < 1e-12:
        result = 0.0
    result = float(f'{result:.15g}')  # drop binary noise (48.280319999999996 -> 48.28032)
    return {'value': value, 'from_unit': s_from, 'to_unit': s_to, 'result': result, 'dimension': dim,
            'dimension_label': DIMENSION_LABELS[dim], 'factor': factor, 'formula': formula,
            'input': {'from_unit': from_unit, 'to_unit': to_unit}}


# --------------------------------------------------------------------------- tools

def _sources() -> list[Source]:
    return [Source(title='Calcul exact local (évaluateur AURORA)', kind='local', retrieved_at=now_iso())]


class EvaluateParams(Params):
    expression: str = Field(min_length=1, max_length=MAX_EXPR_CHARS)


@tool('calc.evaluate', description='Calcul arithmétique exact (opérateurs, parenthèses, fonctions mathématiques).',
      action='system.read', params=EvaluateParams, provenance='calc', timeout_s=5)
def evaluate_tool(p: EvaluateParams) -> ToolResult:
    data = evaluate_expression(p.expression)
    summary = f"{data['pretty']} = {data['result_text']}"
    return ToolResult(ok=True, data=data, summary=summary, provenance='calc', sources=_sources())


class ConvertParams(Params):
    value: float
    from_unit: str = Field(min_length=1, max_length=60, validation_alias=AliasChoices('from_unit', 'from', 'source'))
    to_unit: str = Field(min_length=1, max_length=60, validation_alias=AliasChoices('to_unit', 'to', 'target'))

    @model_validator(mode='before')
    @classmethod
    def _units_present(cls, values):
        if isinstance(values, dict):
            if not any(values.get(k) for k in ('from_unit', 'from', 'source')):
                raise ValueError('unité de départ manquante ou non reconnue')
            if not any(values.get(k) for k in ('to_unit', 'to', 'target')):
                raise ValueError("unité d'arrivée manquante ou non reconnue")
        return values


@tool('calc.convert', description='Conversion d\'unités (longueur, masse, température, volume, vitesse, données, durée, énergie).',
      action='system.read', params=ConvertParams, provenance='calc', timeout_s=5)
def convert_tool(p: ConvertParams) -> ToolResult:
    data = convert_units(p.value, p.from_unit, p.to_unit)
    summary = f"{format_number(p.value)} {data['from_unit']} = {format_number(data['result'])} {data['to_unit']}"
    return ToolResult(ok=True, data=data, summary=summary, provenance='calc', sources=_sources())
